import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  AlertTriangle, BarChart3, BookOpen, Building2, CalendarDays, CalendarRange, CheckCircle2, ChevronDown,
  ClipboardList, Download, Eye, FileSpreadsheet, FileText, Filter, Home, LogOut, PackageCheck, Pencil,
  Plus, Printer, RefreshCw, Save, Search, Settings, ShoppingCart, Sparkles, Target, Trash2, Truck, Upload,
  Users, Warehouse, X, Boxes, Clock3, Image as ImageIcon, KeyRound, ToggleLeft, ToggleRight, Check, Send
} from 'lucide-react';

type User={id:string;email:string;full_name:string;role:string;status:string;institution_id?:string|null;must_change_password?:number;login_code?:string|null};
type Bootstrap={user:User;seasons:any[];grades:any[];publishers:any[];institutions:any[];staff:any[];subjects:string[]};
const MONTHS=[{v:'09',n:'Eylül'},{v:'10',n:'Ekim'},{v:'11',n:'Kasım'},{v:'12',n:'Aralık'},{v:'01',n:'Ocak'},{v:'02',n:'Şubat'},{v:'03',n:'Mart'},{v:'04',n:'Nisan'},{v:'05',n:'Mayıs'},{v:'06',n:'Haziran'}];
const fmtMoney=(n:any)=>new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:0}).format(Number(n||0)/100);
const fmtDate=(s?:string)=>s?new Intl.DateTimeFormat('tr-TR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${String(s).slice(0,10)}T12:00:00`)):'—';
const fmtShort=(s?:string)=>s?new Intl.DateTimeFormat('tr-TR',{day:'2-digit',month:'short'}).format(new Date(`${String(s).slice(0,10)}T12:00:00`)):'—';
const monthName=(v?:string)=>MONTHS.find(m=>m.v===v)?.n||'';
const roleName=(r:string)=>({SUPER_ADMIN:'Süper Admin',ADMIN:'Yönetici',PERSONEL:'Satış Personeli',OPERASYON:'Operasyon',KURUM:'Kurum'} as any)[r]||r;
const isAdmin=(u:User)=>['SUPER_ADMIN','ADMIN'].includes(u.role);

async function api(path:string,opts:RequestInit={}):Promise<any>{const headers:any={'Content-Type':'application/json',...(opts.headers||{})};const r=await fetch(path,{...opts,headers,credentials:'same-origin'});const data:any=await r.json().catch(()=>({ok:false,error:'Sunucudan geçersiz yanıt'}));if(r.status===401&&path!='/api/auth/login'&&path!='/api/auth/me')location.reload();if(!r.ok||data.ok===false)throw new Error(data.error||'İşlem başarısız');return data}
async function apiForm(path:string,form:FormData):Promise<any>{const r=await fetch(path,{method:'POST',body:form,credentials:'same-origin'});const data:any=await r.json().catch(()=>({ok:false,error:'Sunucudan geçersiz yanıt'}));if(r.status===401)location.reload();if(!r.ok||data.ok===false)throw new Error(data.error||'İşlem başarısız');return data}
function useAsync<T=any>(factory:()=>Promise<T>,deps:any[]=[]){const[data,setData]=useState<T|null>(null),[loading,setLoading]=useState(true),[error,setError]=useState('');const run=async()=>{setLoading(true);setError('');try{setData(await factory())}catch(e:any){setError(e.message||String(e))}finally{setLoading(false)}};useEffect(()=>{run()},deps);return{data,loading,error,reload:run,setData}}

function CosmicLogo({compact=false}:{compact?:boolean}){return <div className={`cosmic-logo ${compact?'compact':''}`} aria-label="Yıldız Yayın"><div className="cosmic-orbit orbit-one"><span className="cosmic-planet planet-one"/><span className="cosmic-book book-one"><BookOpen size={compact?9:12}/></span></div><div className="cosmic-orbit orbit-two"><span className="cosmic-planet planet-two"/><span className="cosmic-book book-two"><BookOpen size={compact?8:11}/></span></div><div className="cosmic-core">★</div></div>}
function BrandLockup({compact=false}:{compact?:boolean}){return <div className={`brand-lockup ${compact?'compact':''}`}><CosmicLogo compact={compact}/><div className="brand-copy"><b>YILDIZ YAYIN</b><span>BASIM DAĞITIM HİZMETLERİ</span><small>Bilginin Yörüngesinde.</small></div></div>}


export default function App(){const[user,setUser]=useState<User|null>(null),[boot,setBoot]=useState<Bootstrap|null>(null),[checking,setChecking]=useState(true);const load=async()=>{setChecking(true);try{const me=await api('/api/auth/me');setUser(me.user);setBoot(await api('/api/bootstrap'))}catch{setUser(null);setBoot(null)}finally{setChecking(false)}};useEffect(()=>{load()},[]);if(checking)return <Splash text="Platform hazırlanıyor…"/>;if(!user)return <><FinalCss/><Login onLogin={async u=>{setUser(u);setBoot(await api('/api/bootstrap'))}}/></>;if(!boot)return <Splash text="Veriler yükleniyor…"/>;return <><FinalCss/><Shell user={user} boot={boot} refreshBoot={async()=>setBoot(await api('/api/bootstrap'))} onLogout={async()=>{try{await api('/api/auth/logout',{method:'POST'})}catch{}location.reload()}}/></>}
function Splash({text}:{text:string}){return <div className="splash"><BrandLockup/><strong>Yıldız Deneme Platformu</strong><small>{text}</small></div>}
function Login({onLogin}:{onLogin:(u:User)=>void}){const[idn,setIdn]=useState('admin@yildizyayin.com'),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setError('');try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({identifier:idn,password})});onLogin(d.user)}catch(e:any){setError(e.message)}finally{setBusy(false)}};return <div className="login-page"><div className="login-stars"/><div className="login-card"><div className="login-brand"><BrandLockup/><div className="login-product"><h1>Yıldız Deneme</h1><p>Takvim · Sipariş · Tedarik · Teslimat</p></div></div><h2>Platforma giriş yapın</h2><p className="muted">Yönetici/personel e-posta ile, kurumlar kurum kodu ile giriş yapabilir.</p><form onSubmit={submit}><label>E-posta / Kurum Kodu<input value={idn} onChange={e=>setIdn(e.target.value)} required autoFocus/></label><label>Şifre<input value={password} onChange={e=>setPassword(e.target.value)} type="password" required/></label>{error&&<div className="error-box">{error}</div>}<button className="btn primary wide" disabled={busy}>{busy?'Giriş yapılıyor…':'Giriş Yap'}</button></form><div className="login-foot">Yıldız Yayın Basım Dağıtım Hizmetleri</div></div></div>}

const institutionNav=[
 {key:'dashboard',label:'Ana Sayfa',icon:Home},
 {key:'exams',label:'Denemeler',icon:BookOpen,subs:['Deneme Seç','Takvimim','Cevap Anahtarları']},
 {key:'operations',label:'Operasyon',icon:Truck,subs:['Gelen / Gelecek Denemeler']}
];
const nav=[
 {key:'dashboard',label:'Ana Sayfa',icon:Home},
 {key:'exams',label:'Denemeler',icon:BookOpen,subs:['Deneme Kataloğu','Deneme Takvimi','Cevap Anahtarları']},
 {key:'institutions',label:'Kurumlar',icon:Building2,subs:['Kurumlar','Deneme Planları','Kurum Takvimleri']},
 {key:'sales',label:'Satış',icon:ShoppingCart,subs:['Satış Fırsatları','Sipariş Bekleyenler','Siparişler']},
 {key:'publishers',label:'Yayınevleri',icon:Warehouse,subs:['Yayınevleri','Sipariş Listeleri']},
 {key:'operations',label:'Operasyon',icon:Truck,subs:['Tedarik','Gelen Ürünler','Teslimatlar']},
 {key:'reports',label:'Raporlar',icon:BarChart3},
 {key:'management',label:'Yönetim',icon:Settings,roles:['SUPER_ADMIN','ADMIN'],subs:['Kullanıcılar','Sezonlar','Ayarlar','Entegrasyonlar']}
];
function Shell({user,boot,refreshBoot,onLogout}:{user:User;boot:Bootstrap;refreshBoot:()=>Promise<void>;onLogout:()=>void}){const[section,setSection]=useState('dashboard'),[sub,setSub]=useState(''),[mobile,setMobile]=useState(false);const visible=user.role==='KURUM'?institutionNav:nav.filter(n=>!n.roles||n.roles.includes(user.role));const choose=(k:string,s='')=>{setSection(k);setSub(s);setMobile(false)};return <><div className="app-shell"><aside className={`sidebar ${mobile?'open':''}`}><div className="brand"><BrandLockup compact/></div><nav>{visible.map(n=>{const I=n.icon;return <div key={n.key}><button className={`nav-main ${section===n.key?'active':''}`} onClick={()=>choose(n.key,n.subs?.[0]||'')}><I size={19}/><span>{n.label}</span>{n.subs&&<ChevronDown size={14}/>}</button>{section===n.key&&n.subs&&<div className="subnav">{n.subs.map(s=><button key={s} className={sub===s?'active':''} onClick={()=>setSub(s)}>{s}</button>)}</div>}</div>})}</nav><div className="sidebar-foot"><div className="user-mini"><div className="avatar">{user.full_name?.[0]||'Y'}</div><div><b>{user.full_name}</b><small>{roleName(user.role)}</small></div></div><button className="icon-btn" onClick={onLogout}><LogOut size={18}/></button></div></aside><main className="main-area"><header className="topbar"><button className="mobile-menu" onClick={()=>setMobile(!mobile)}>☰</button><div><span className="eyebrow">2026–2027 Deneme Sezonu</span><h2>{sub||({dashboard:'Genel Bakış',reports:'Ticari Raporlar'} as any)[section]||'Yıldız Deneme'}</h2></div><div className="top-actions"><span className="status-dot">● Sistem aktif</span></div></header><div className="content">{user.role==='KURUM'?<>{section==='dashboard'&&<InstitutionDashboard boot={boot}/>} {section==='exams'&&(sub==='Takvimim'?<InstitutionCalendar boot={boot} user={user}/>:sub==='Cevap Anahtarları'?<AnswerKeys boot={boot} user={user}/>:<PlanBuilder boot={boot} user={user}/>)} {section==='operations'&&<InstitutionOperations/>}</>:<>{section==='dashboard'&&<Dashboard user={user}/>} {section==='exams'&&<Exams boot={boot} sub={sub} user={user}/>} {section==='institutions'&&<Institutions boot={boot} sub={sub} user={user} refreshBoot={refreshBoot}/>} {section==='sales'&&<Sales boot={boot} sub={sub} user={user}/>} {section==='publishers'&&<Publishers boot={boot} sub={sub} user={user} refreshBoot={refreshBoot}/>} {section==='operations'&&<Operations boot={boot} sub={sub}/>} {section==='reports'&&<Reports/>} {section==='management'&&<Management boot={boot} sub={sub} refreshBoot={refreshBoot}/>}</>}</div></main></div>{user.must_change_password?<ChangePasswordModal/>:null}</>}
function ChangePasswordModal(){const[current,setCurrent]=useState(''),[next,setNext]=useState(''),[again,setAgain]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');const save=async()=>{setError('');if(next.length<10)return setError('Yeni şifre en az 10 karakter olmalı.');if(next!==again)return setError('Yeni şifreler eşleşmiyor.');setBusy(true);try{await api('/api/auth/change-password',{method:'POST',body:JSON.stringify({current_password:current,new_password:next})});location.reload()}catch(e:any){setError(e.message)}finally{setBusy(false)}};return <div className="modal-back force"><div className="modal small-modal"><div className="modal-head"><div><span className="eyebrow">Güvenlik</span><h2>Geçici şifrenizi değiştirin</h2></div></div><Field label="Mevcut geçici şifre"><input type="password" value={current} onChange={e=>setCurrent(e.target.value)}/></Field><Field label="Yeni şifre"><input type="password" value={next} onChange={e=>setNext(e.target.value)}/></Field><Field label="Yeni şifre tekrar"><input type="password" value={again} onChange={e=>setAgain(e.target.value)}/></Field>{error&&<div className="error-box">{error}</div>}<button className="btn primary wide" disabled={busy} onClick={save}>Şifremi Değiştir</button></div></div>}

function InstitutionDashboard({boot}:{boot:Bootstrap}){const orders=useAsync(()=>api('/api/orders'),[]),plans=useAsync(()=>{const season=boot.seasons.find(s=>s.is_active)?.id||'';return api(`/api/plans?season_id=${season}`)},[]);if(orders.loading||plans.loading)return <Loading/>;const os=((orders.data as any)?.items||[]).filter((x:any)=>x.status!=='IPTAL'),ps=(plans.data as any)?.items||[];const arrived=os.filter((x:any)=>x.delivered_at),coming=os.filter((x:any)=>!x.delivered_at);return <><div className="institution-hero"><BrandLockup/><div><span className="pill gold"><Sparkles size={14}/> Kurum Deneme Merkezi</span><h1>Denemelerinizi seçin, siparişinizi onaylayın ve teslimatı takip edin.</h1><p>Bu panel yalnız kurumunuzun deneme planı, takvimi, siparişleri ve gelen/gelecek denemelerini gösterir.</p></div></div><div className="kpi-grid"><Kpi icon={CalendarDays} label="Planlanan Deneme" value={ps.length} sub="Kurum takviminizde"/><Kpi icon={ShoppingCart} label="Onaylı Sipariş" value={os.length} sub={`${os.reduce((t:number,x:any)=>t+Number(x.quantity||0),0)} adet`}/><Kpi icon={Truck} label="Gelecek Deneme" value={coming.length} sub="Teslimat bekliyor"/><Kpi icon={PackageCheck} label="Gelen Deneme" value={arrived.length} sub="Kuruma teslim edildi"/></div><Panel title="Yaklaşan siparişleriniz" icon={Clock3}>{coming.length?<DataTable cols={['Sınıf','Yayınevi','Deneme','Adet','Tahmini Sevk','Uygulama']} rows={coming.slice(0,8).map((x:any)=>[x.grade_name,x.publisher_name,x.exam_name,x.quantity,fmtDate(x.estimated_ship_date),`${fmtShort(x.application_start_date)}–${fmtShort(x.application_end_date)}`])}/>:<Empty text="Bekleyen deneme siparişiniz yok."/>}</Panel></>}


function Dashboard({user}:{user:User}){const q=useAsync(()=>api('/api/dashboard'),[]);if(q.loading)return <Loading/>;if(q.error)return <ErrorState text={q.error} retry={q.reload}/>;const d:any=q.data||{};return <><div className="hero"><div><span className="pill gold"><Sparkles size={14}/> Sezon Kontrol Merkezi</span><h1>{user.role==='KURUM'?'Takviminizi ve siparişlerinizi yönetin.':'Deneme sezonunun tamamı tek ekranda.'}</h1><p>{user.role==='KURUM'?'Seçtiğiniz sınavları planlayın, adetleri onaylayın ve teslimatı takip edin.':'Yaklaşan sınavları, acil siparişleri, planlanan satışları ve operasyonu kaçırmayın.'}</p></div><div className="hero-orbit">★</div></div><div className="kpi-grid"><Kpi icon={ShoppingCart} label="Toplam Sipariş" value={d.orders?.total||0} sub={`${d.orders?.quantity||0} adet`}/><Kpi icon={BarChart3} label="Ciro" value={fmtMoney(d.orders?.revenue)} sub={`${d.orders?.pending||0} aktif sipariş`}/><Kpi icon={CalendarDays} label="Yaklaşan Sınav" value={d.upcoming||0} sub="Önümüzdeki 30 gün"/><Kpi icon={Target} label="Satış Fırsatı" value={d.opportunities||0} sub={`${d.plan_pending||0} sipariş bekliyor`}/><Kpi icon={Truck} label="Teslimat Bekliyor" value={d.pending_deliveries||0} sub="Operasyon takibi"/></div><div className="grid-2"><Panel title="Yaklaşan son sipariş tarihleri" icon={Clock3}>{d.deadlines?.length?d.deadlines.map((x:any)=><div className="deadline" key={x.id}><div><b>{x.name}</b><small>{x.publisher} · {x.grade}{x.subject?` · ${x.subject}`:''}</small></div><span>{fmtShort(x.last_order_date)}</span></div>):<Empty text="Yaklaşan kritik tarih yok."/>}</Panel><Panel title="Hızlı kontrol" icon={Sparkles}><ActionRow tone="warn" title={`${d.plan_pending||0} sipariş bekleyen plan`} text="Adedi girilmiş fakat henüz siparişe dönüşmemiş kurum planları."/><ActionRow tone="info" title={`${d.pending_deliveries||0} teslimat tamamlanmadı`} text="Uygulama tarihinden önce teslimatları kapatın."/></Panel></div></>}
function Kpi({icon:I,label,value,sub}:{icon:any;label:string;value:any;sub:string}){return <div className="kpi"><div className="kpi-icon"><I size={20}/></div><span>{label}</span><strong>{value}</strong><small>{sub}</small></div>}
function Panel({title,icon:I,children}:{title:string;icon:any;children:any}){return <section className="panel"><div className="panel-head"><div><I size={18}/><h3>{title}</h3></div></div>{children}</section>}
function ActionRow({tone,title,text}:{tone:string;title:string;text:string}){return <div className={`action-row ${tone}`}><AlertTriangle size={18}/><div><b>{title}</b><small>{text}</small></div></div>}

// EXAMS
function Exams({boot,sub,user}:{boot:Bootstrap;sub:string;user:User}){if(sub==='Cevap Anahtarları')return <AnswerKeys boot={boot} user={user}/>;return sub==='Deneme Takvimi'?<MasterCalendar boot={boot}/>:<ExamCatalog boot={boot} canEdit={isAdmin(user)}/>}
const DIGITAL_TYPES:any={CEVAP_PDF:'Cevap Anahtarı PDF',KAZANIM_EXCEL:'Kazanım Tablosu',DENEME_PDF:'Deneme PDF',OPTIK_DOKUMAN:'Optik Dokümanı',SEKONIC:'Sekonic',BICOM:'Bicom',DIJITAL_FORMAT:'Diğer Dijital Dosya',VIDEO_URL:'Video Çözüm'};
const STAGES=[{key:'ILKOKUL',label:'İlkokul',codes:['1','2','3','4']},{key:'ORTAOKUL',label:'Ortaokul',codes:['5','6','7','8']},{key:'LISE',label:'Lise',codes:['9','10','11','TYT','AYT','YDT']}];
const opticalTypes=new Set(['OPTIK_DOKUMAN','SEKONIC','BICOM']);
function AnswerKeys({boot,user}:{boot:Bootstrap;user:User}){const canManage=user.role==='SUPER_ADMIN';const examsQ=useAsync(()=>canManage?api('/api/exams?active=1'):Promise.resolve({items:[]}),[canManage]);const assetsQ=useAsync(()=>api(`/api/digital-assets${canManage?'?active=all':''}`),[canManage]);const[open,setOpen]=useState<Set<string>>(new Set(['stage:LISE'])),[modal,setModal]=useState<any|null>(null);const toggle=(k:string)=>setOpen(v=>{const n=new Set(v);n.has(k)?n.delete(k):n.add(k);return n});const assets=(assetsQ.data as any)?.items||[];const exams=useMemo(()=>{if(canManage)return (examsQ.data as any)?.items||[];const seen=new Map<string,any>();for(const a of assets)if(!seen.has(a.exam_id))seen.set(a.exam_id,{id:a.exam_id,season_id:a.season_id,grade_level_id:a.grade_level_id,name:a.exam_name,code:a.exam_code,publisher_id:a.publisher_id,publisher_name:a.publisher_name,publisher_short:a.publisher_short,grade_name:a.grade_name,grade_code:a.grade_code});return [...seen.values()]},[canManage,examsQ.data,assetsQ.data]);const reload=()=>assetsQ.reload();const act=async(a:any)=>{await api(`/api/digital-assets/${a.id}`,{method:'PATCH',body:JSON.stringify({is_active:a.is_active?0:1})});reload()};const del=async(a:any)=>{if(!confirm(`${a.title||a.file_name||DIGITAL_TYPES[a.asset_type]} kalıcı olarak silinsin mi?`))return;await api(`/api/digital-assets/${a.id}`,{method:'DELETE'});reload()};if(assetsQ.loading||examsQ.loading)return <Loading/>;return <><div className="archive-hero"><div><span className="pill gold"><FileText size={14}/> Belge Arşivi</span><h2>Cevap Anahtarları</h2><p>İlkokul / Ortaokul / Lise → Yayınevi → Sezon → Sınıf → Deneme → Belge yapısı.</p></div>{canManage&&<button className="btn primary" onClick={()=>setModal({})}><Upload size={16}/> Yeni Belge Yükle</button>}</div><div className="archive-tree">{STAGES.map(stage=>{const stageExams=exams.filter((e:any)=>stage.codes.includes(String(e.grade_code||boot.grades.find(g=>g.id===e.grade_level_id)?.code||'')));const pubIds=[...new Set(stageExams.map((e:any)=>e.publisher_id))];if(!canManage&&!stageExams.length)return null;return <ArchiveFolder key={stage.key} depth={0} label={stage.label} nodeKey={`stage:${stage.key}`} open={open} toggle={toggle} meta={`${stageExams.length} deneme`} icon="school">{pubIds.map((pid:any)=>{const pub=boot.publishers.find(p=>p.id===pid)||stageExams.find((e:any)=>e.publisher_id===pid)||{};const pubExams=stageExams.filter((e:any)=>e.publisher_id===pid);const seasonIds=[...new Set(pubExams.map((e:any)=>e.season_id))];return <ArchiveFolder key={pid} depth={1} label={pub.short_name||pub.name||'Yayınevi'} nodeKey={`pub:${stage.key}:${pid}`} open={open} toggle={toggle} meta="Yayınevi" icon="publisher">{seasonIds.sort((a:any,z:any)=>(boot.seasons.find(s=>s.id===z)?.year_start||0)-(boot.seasons.find(s=>s.id===a)?.year_start||0)).map((sid:any)=>{const season=boot.seasons.find(s=>s.id===sid)||{id:sid,name:'Sezon'};const se=pubExams.filter((e:any)=>e.season_id===sid);const gradeIds=[...new Set(se.map((e:any)=>e.grade_level_id))];return <ArchiveFolder key={sid} depth={2} label={season.name} nodeKey={`season:${stage.key}:${pid}:${sid}`} open={open} toggle={toggle} meta="Sezon" icon="season">{gradeIds.sort((a:any,z:any)=>(boot.grades.find(g=>g.id===a)?.sort_order||0)-(boot.grades.find(g=>g.id===z)?.sort_order||0)).map((gid:any)=>{const grade=boot.grades.find(g=>g.id===gid)||se.find((e:any)=>e.grade_level_id===gid)||{};const ge=se.filter((e:any)=>e.grade_level_id===gid);return <ArchiveFolder key={gid} depth={3} label={grade.name||grade.grade_name||'Sınıf'} nodeKey={`grade:${stage.key}:${pid}:${sid}:${gid}`} open={open} toggle={toggle} meta={`${ge.length} deneme`} icon="grade">{ge.map((e:any)=>{const ef=assets.filter((a:any)=>a.exam_id===e.id);const direct=ef.filter((a:any)=>!opticalTypes.has(a.asset_type));const optical=ef.filter((a:any)=>opticalTypes.has(a.asset_type));const formCodes:string[]=[...new Set<string>(optical.filter((a:any)=>['SEKONIC','BICOM'].includes(a.asset_type)).map((a:any)=>String(a.form_code||'KODSUZ')))].sort();return <ArchiveFolder key={e.id} depth={4} label={e.name} nodeKey={`exam:${e.id}`} open={open} toggle={toggle} meta={e.code} icon="exam" actions={canManage?<button className="tree-add" onClick={ev=>{ev.stopPropagation();setModal({exam_id:e.id})}}><Plus size={13}/> Belge</button>:null}>{direct.map((a:any)=><ArchiveFile key={a.id} a={a} depth={5} canManage={canManage} edit={()=>setModal({item:a,exam_id:e.id})} toggleActive={()=>act(a)} remove={()=>del(a)}/>)}{optical.length>0&&<ArchiveFolder depth={5} label="Optik Dokümanları / Formları" nodeKey={`optical:${e.id}`} open={open} toggle={toggle} meta={`${optical.length} dosya`} icon="optical">{optical.filter((a:any)=>a.asset_type==='OPTIK_DOKUMAN').map((a:any)=><ArchiveFile key={a.id} a={a} depth={6} canManage={canManage} edit={()=>setModal({item:a,exam_id:e.id})} toggleActive={()=>act(a)} remove={()=>del(a)}/>)}{formCodes.map(code=><ArchiveFolder key={code} depth={6} label={`Form Kodu: ${code}`} nodeKey={`form:${e.id}:${code}`} open={open} toggle={toggle} meta="Sekonic / Bicom" icon="form">{optical.filter((a:any)=>String(a.form_code||'KODSUZ')===code&&['SEKONIC','BICOM'].includes(a.asset_type)).sort((a:any,z:any)=>a.asset_type.localeCompare(z.asset_type)).map((a:any)=><ArchiveFile key={a.id} a={a} depth={7} canManage={canManage} edit={()=>setModal({item:a,exam_id:e.id})} toggleActive={()=>act(a)} remove={()=>del(a)} directLabel={a.asset_type==='SEKONIC'?'Sekonic':'Bicom'}/>)}</ArchiveFolder>)}</ArchiveFolder>}{!ef.length&&canManage&&<div className="tree-empty" style={{paddingLeft:182}}>Henüz belge yüklenmemiş.</div>}</ArchiveFolder>})}</ArchiveFolder>})}</ArchiveFolder>})}</ArchiveFolder>})}</ArchiveFolder>})}</div>{modal&&<DigitalAssetModal exams={exams} item={modal.item||null} initialExam={modal.exam_id||''} close={()=>setModal(null)} saved={()=>{setModal(null);reload()}}/>}</>}
function ArchiveFolder({depth,label,nodeKey,open,toggle,meta,icon,actions,children}:{depth:number;label:string;nodeKey:string;open:Set<string>;toggle:(k:string)=>void;meta?:string;icon?:string;actions?:any;children:any}){const isOpen=open.has(nodeKey);return <div className="tree-node"><div className={`tree-folder depth-${Math.min(depth,7)}`} style={{paddingLeft:14+depth*24}} onClick={()=>toggle(nodeKey)} role="button" tabIndex={0} onKeyDown={e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle(nodeKey)}}}><span className={`tree-caret ${isOpen?'open':''}`}>›</span><span className={`tree-folder-icon ${icon||''}`}>📁</span><b>{label}</b>{meta&&<small>{meta}</small>}<span className="tree-spacer"/>{actions}</div>{isOpen&&<div className="tree-children">{children}</div>}</div>}
function ArchiveFile({a,depth,canManage,edit,toggleActive,remove,directLabel}:{a:any;depth:number;canManage:boolean;edit:()=>void;toggleActive:()=>void;remove:()=>void;directLabel?:string}){const label=directLabel||a.title||DIGITAL_TYPES[a.asset_type]||a.asset_type;const href=a.external_url||`/api/digital-assets/${a.id}/download`;return <div className={`tree-file ${a.is_active?'':'inactive'}`} style={{paddingLeft:38+depth*24}}><a href={href} target={a.external_url?'_blank':undefined} rel="noreferrer" title="İndir / Aç"><span className="tree-file-icon">{a.asset_type==='KAZANIM_EXCEL'?'▣':'☁'}</span><b>{label}</b><small>{a.file_name||a.format_name||a.external_url||''}</small>{a.form_code&&<em>{a.form_code}</em>}</a>{canManage&&<Actions><Badge text={a.is_active?'Aktif':'Pasif'} tone={a.is_active?'good':'muted'}/><button onClick={edit} title="Düzenle / dosyayı değiştir"><Pencil size={14}/></button><button onClick={toggleActive} title={a.is_active?'Pasif yap':'Aktif yap'}>{a.is_active?<ToggleRight size={16}/>:<ToggleLeft size={16}/>}</button><button className="danger" onClick={remove} title="Sil"><Trash2 size={14}/></button></Actions>}</div>}
function DigitalAssetModal({exams,item,initialExam,close,saved}:{exams:any[];item?:any|null;initialExam?:string;close:()=>void;saved:()=>void}){const[b,setB]=useState<any>(item?{...item}:{exam_id:initialExam||exams[0]?.id||'',asset_type:'CEVAP_PDF',is_active:1}),[file,setFile]=useState<File|null>(null);const isForm=['SEKONIC','BICOM'].includes(b.asset_type);const save=async()=>{if(isForm&&!String(b.form_code||'').trim())throw new Error('Sekonic/Bicom için optik form kodu zorunlu.');if(!item){const f=new FormData();for(const k of ['exam_id','asset_type','title','format_name','form_code','external_url'])if(b[k])f.append(k,String(b[k]));if(file)f.append('file',file);await apiForm('/api/digital-assets',f)}else{await api(`/api/digital-assets/${item.id}`,{method:'PATCH',body:JSON.stringify({asset_type:b.asset_type,title:b.title||null,format_name:b.format_name||null,form_code:b.form_code||null,external_url:b.external_url||null,is_active:b.is_active?1:0})});if(file){const f=new FormData();f.append('file',file);await apiForm(`/api/digital-assets/${item.id}/replace`,f)}}saved()};return <Modal title={item?'Belgeyi düzenle / değiştir':'Yeni belge yükle'} close={close}><FormGrid><Field label="Deneme"><select value={b.exam_id||''} disabled={!!item} onChange={e=>setB({...b,exam_id:e.target.value})}><option value="">Seçiniz</option>{exams.map((x:any)=><option key={x.id} value={x.id}>{x.publisher_short||x.publisher_name} · {x.grade_name} · {x.name}</option>)}</select></Field><Field label="Belge türü"><select value={b.asset_type} disabled={!!item} onChange={e=>setB({...b,asset_type:e.target.value})}>{Object.entries(DIGITAL_TYPES).map(([k,v]:any)=><option value={k} key={k}>{v}</option>)}</select></Field><Field label="Başlık"><input value={b.title||''} onChange={e=>setB({...b,title:e.target.value})} placeholder={DIGITAL_TYPES[b.asset_type]}/></Field>{isForm&&<Field label="Optik form kodu"><input value={b.form_code||''} onChange={e=>setB({...b,form_code:e.target.value.toUpperCase()})} placeholder="Örn. F001 / TYT-01"/></Field>}{b.asset_type==='OPTIK_DOKUMAN'&&<Field label="Form kodu (isteğe bağlı)"><input value={b.form_code||''} onChange={e=>setB({...b,form_code:e.target.value.toUpperCase()})}/></Field>}{b.asset_type==='DIJITAL_FORMAT'&&<Field label="Format adı"><input value={b.format_name||''} onChange={e=>setB({...b,format_name:e.target.value})} placeholder="Örn. XML / CSV / cihaz formatı"/></Field>}{b.asset_type==='VIDEO_URL'?<Field label="Video bağlantısı"><input type="url" value={b.external_url||''} onChange={e=>setB({...b,external_url:e.target.value})} placeholder="https://..."/></Field>:<Field label={item?'Yeni dosya (değiştirmek istemezseniz boş bırakın)':'Dosya'}><input type="file" onChange={e=>setFile(e.target.files?.[0]||null)} accept={b.asset_type==='CEVAP_PDF'||b.asset_type==='DENEME_PDF'||b.asset_type==='OPTIK_DOKUMAN'?'.pdf':b.asset_type==='KAZANIM_EXCEL'?'.xlsx,.xls,.csv':b.asset_type==='SEKONIC'?'.fmt,.txt,.dat,.xml,.csv':'*/*'}/></Field>}{item&&<label className="check"><input type="checkbox" checked={!!b.is_active} onChange={e=>setB({...b,is_active:e.target.checked?1:0})}/> Aktif</label>}</FormGrid><div className="info-box">Kurum ve personel kullanıcıları bu arşivde yalnız görüntüleme ve indirme yapabilir. Yükleme, değiştirme, aktif/pasif ve silme işlemleri yalnız Süper Admin'e açıktır.</div><ModalActions close={close} save={save}/></Modal>}

function ExamCatalog({boot,canEdit}:{boot:Bootstrap;canEdit:boolean}){const[season,setSeason]=useState(boot.seasons.find(s=>s.is_active)?.id||boot.seasons[0]?.id||''),[grade,setGrade]=useState(''),[active,setActive]=useState('1'),[q,setQ]=useState(''),[edit,setEdit]=useState<any|null>(null),[bulk,setBulk]=useState(false);const list=useAsync(()=>api(`/api/exams?season_id=${season}${grade?`&grade_level_id=${grade}`:''}${active?`&active=${active}`:''}${q?`&q=${encodeURIComponent(q)}`:''}`),[season,grade,active,q]);const items=(list.data as any)?.items||[];const remove=async(x:any)=>{if(!confirm(`${x.name} kaydını silmek/pasife almak istiyor musunuz?`))return;await api(`/api/exams/${x.id}`,{method:'DELETE'});list.reload()};const toggle=async(x:any)=>{await api(`/api/exams/${x.id}`,{method:'PATCH',body:JSON.stringify({is_active:!x.is_active})});list.reload()};const exportXlsx=async()=>{const XLSX=await import('xlsx');const rows=items.map((x:any)=>({Yayınevi:x.publisher_name,Sınıf:x.grade_name,'Sınav Türü':x.exam_type,Ders:x.subject||'',Deneme:x.name,Kod:x.code,'Son Sipariş':x.last_order_date,'Sevk':x.estimated_ship_date,'Uygulama Başlangıç':x.application_start_date,'Uygulama Bitiş':x.application_end_date,'Liste Fiyatı':Number(x.list_price||0)/100,'Alış Fiyatı':Number(x.purchase_price||0)/100,'Satış Fiyatı':Number(x.default_sale_price||0)/100,'Minimum Sipariş':x.minimum_order,Aktif:x.is_active?'Evet':'Hayır'}));const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'Denemeler');XLSX.writeFile(wb,'Yildiz-Deneme-Katalogu.xlsx')};return <><Toolbar><select value={season} onChange={e=>setSeason(e.target.value)}>{boot.seasons.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select><select value={grade} onChange={e=>setGrade(e.target.value)}><option value="">Tüm sınıflar</option>{boot.grades.map(g=><option value={g.id} key={g.id}>{g.name}</option>)}</select><select value={active} onChange={e=>setActive(e.target.value)}><option value="1">Aktif</option><option value="0">Pasif</option><option value="">Tümü</option></select><SearchBox value={q} set={setQ}/><div className="spacer"/>{canEdit&&<button className="btn" onClick={()=>setBulk(true)}><Upload size={16}/> İçe Aktar</button>}<button className="btn" onClick={exportXlsx}><Download size={16}/> Dışa Aktar</button>{canEdit&&<button className="btn primary" onClick={()=>setEdit({})}><Plus size={16}/> Deneme Ekle</button>}</Toolbar>{list.loading?<Loading/>:<DataTable cols={['Tarih','Sınıf','Tür','Yayınevi','Deneme','Kod','Son Sipariş','Satış','Durum','İşlem']} rows={items.map((x:any)=>[fmtShort(x.application_start_date),x.grade_name,x.exam_type==='DERS_SINAVI'?`Ders · ${x.subject||'—'}`:'Deneme',x.publisher_short||x.publisher_name,x.name,x.code,fmtDate(x.last_order_date),fmtMoney(x.default_sale_price),<Badge key="b" text={x.is_active?'Aktif':'Pasif'} tone={x.is_active?'good':'muted'}/>,canEdit?<Actions key="a"><button onClick={()=>setEdit(x)} title="Düzenle"><Pencil size={15}/></button><button onClick={()=>toggle(x)} title={x.is_active?'Pasif yap':'Aktif yap'}>{x.is_active?<ToggleRight size={17}/>:<ToggleLeft size={17}/>}</button><button className="danger" onClick={()=>remove(x)} title="Sil/Pasife al"><Trash2 size={15}/></button></Actions>:'—'])}/>} {edit&&<ExamModal boot={boot} season={season} item={edit.id?edit:null} close={()=>setEdit(null)} saved={()=>{setEdit(null);list.reload()}}/>}{bulk&&<ExamBulkModal boot={boot} season={season} close={()=>setBulk(false)} saved={()=>{setBulk(false);list.reload()}}/>}</>}
function ExamModal({boot,season,item,close,saved}:{boot:Bootstrap;season:string;item:any|null;close:()=>void;saved:()=>void}){const[b,setB]=useState<any>(item?{...item,list_price:Number(item.list_price||0)/100,purchase_price:Number(item.purchase_price||0)/100,default_sale_price:Number(item.default_sale_price||0)/100}:{season_id:season,publisher_id:boot.publishers[0]?.id,grade_level_id:boot.grades[0]?.id,minimum_order:1,exam_type:'DENEME',is_active:1});const save=async()=>{const payload={...b,list_price:Math.round(Number(b.list_price||0)*100),purchase_price:Math.round(Number(b.purchase_price||0)*100),default_sale_price:Math.round(Number(b.default_sale_price||0)*100),subject:b.exam_type==='DERS_SINAVI'?b.subject||null:null};await api(item?`/api/exams/${item.id}`:'/api/exams',{method:item?'PATCH':'POST',body:JSON.stringify(payload)});saved()};return <Modal title={item?'Denemeyi düzenle':'Yeni sınav / deneme'} close={close}><FormGrid><Field label="Yayınevi"><select value={b.publisher_id||''} onChange={e=>setB({...b,publisher_id:e.target.value})}>{boot.publishers.map(p=><option value={p.id} key={p.id}>{p.name}</option>)}</select></Field><Field label="Sınıf düzeyi"><select value={b.grade_level_id||''} onChange={e=>setB({...b,grade_level_id:e.target.value})}>{boot.grades.map(g=><option value={g.id} key={g.id}>{g.name}</option>)}</select></Field><Field label="Sınav türü"><select value={b.exam_type||'DENEME'} onChange={e=>setB({...b,exam_type:e.target.value})}><option value="DENEME">Türkiye Geneli / Kurum Denemesi</option><option value="DERS_SINAVI">Ders Sınavı</option></select></Field>{b.exam_type==='DERS_SINAVI'&&<Field label="Ders"><select value={b.subject||''} onChange={e=>setB({...b,subject:e.target.value})}><option value="">Seçiniz</option>{boot.subjects.map(s=><option key={s}>{s}</option>)}</select></Field>}<Field label="Sınav / deneme adı"><input value={b.name||''} onChange={e=>setB({...b,name:e.target.value})}/></Field><Field label="Kod"><input value={b.code||''} onChange={e=>setB({...b,code:e.target.value})}/></Field><Field label="Son sipariş"><input type="date" value={b.last_order_date||''} onChange={e=>setB({...b,last_order_date:e.target.value})}/></Field><Field label="Tahmini sevk"><input type="date" value={b.estimated_ship_date||''} onChange={e=>setB({...b,estimated_ship_date:e.target.value})}/></Field><Field label="Uygulama başlangıcı"><input type="date" value={b.application_start_date||''} onChange={e=>setB({...b,application_start_date:e.target.value})}/></Field><Field label="Uygulama bitişi"><input type="date" value={b.application_end_date||''} onChange={e=>setB({...b,application_end_date:e.target.value})}/></Field><Field label="Liste fiyatı (TL)"><input type="number" value={b.list_price||''} onChange={e=>setB({...b,list_price:e.target.value})}/></Field><Field label="Alış fiyatı (TL)"><input type="number" value={b.purchase_price||''} onChange={e=>setB({...b,purchase_price:e.target.value})}/></Field><Field label="Satış fiyatı (TL)"><input type="number" value={b.default_sale_price||''} onChange={e=>setB({...b,default_sale_price:e.target.value})}/></Field><Field label="Minimum sipariş"><input type="number" value={b.minimum_order||1} onChange={e=>setB({...b,minimum_order:e.target.value})}/></Field></FormGrid><ModalActions close={close} save={save}/></Modal>}
function ExamBulkModal({boot,season,close,saved}:{boot:Bootstrap;season:string;close:()=>void;saved:()=>void}){const[rows,setRows]=useState<any[]>([]),[errors,setErrors]=useState<any[]>([]),[busy,setBusy]=useState(false);const template=async()=>{const XLSX=await import('xlsx');const sample=[{publisher:'Demo Yayınları',grade:'5',exam_type:'DENEME',subject:'',name:'5. Sınıf TG 1',code:'DEMO-5-TG1',last_order_date:'2026-09-01',estimated_ship_date:'2026-09-05',application_start_date:'2026-09-10',application_end_date:'2026-09-12',list_price:150,purchase_price:90,sale_price:120,minimum_order:10}];const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(sample),'Şablon');XLSX.writeFile(wb,'Deneme-Yukleme-Sablonu.xlsx')};const file=async(e:React.ChangeEvent<HTMLInputElement>)=>{const f=e.target.files?.[0];if(!f)return;const XLSX=await import('xlsx');const wb=XLSX.read(await f.arrayBuffer());setRows(XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{defval:''}) as any[])};const upload=async()=>{setBusy(true);try{const d=await api('/api/exams/bulk',{method:'POST',body:JSON.stringify({season_id:season,rows})});setErrors(d.errors||[]);if(!(d.errors||[]).length)saved()}finally{setBusy(false)}};return <Modal title="Toplu sınav / deneme yükle" close={close}><div className="bulk-head"><button className="btn" onClick={template}><FileSpreadsheet size={16}/> Şablonu indir</button><label className="btn"><Upload size={16}/> Excel seç<input hidden type="file" accept=".xlsx,.xls,.csv" onChange={file}/></label></div><p className="muted">Yükleme öncesi {rows.length} satır okundu. Yayınevi ve sınıf mevcut kayıtlarla eşleştirilir.</p>{rows.length>0&&<DataTable cols={['#','Yayınevi','Sınıf','Ad','Kod']} rows={rows.slice(0,8).map((x:any,i)=>[i+2,x.publisher,x.grade,x.name,x.code])}/>} {errors.length>0&&<div className="error-box">{errors.slice(0,10).map((x:any)=><div key={x.row}>Satır {x.row}: {x.error}</div>)}</div>}<div className="modal-actions"><button className="btn" onClick={close}>Vazgeç</button><button className="btn primary" disabled={!rows.length||busy} onClick={upload}>{busy?'Yükleniyor…':`${rows.length} satırı yükle`}</button></div></Modal>}
function MasterCalendar({boot}:{boot:Bootstrap}){const[season,setSeason]=useState(boot.seasons.find(s=>s.is_active)?.id||''),[grade,setGrade]=useState('');const q=useAsync(()=>api(`/api/exams?season_id=${season}&active=1${grade?`&grade_level_id=${grade}`:''}`),[season,grade]);const grouped=useMemo(()=>groupByMonth((q.data as any)?.items||[],'application_start_date'),[q.data]);return <><Toolbar><select value={season} onChange={e=>setSeason(e.target.value)}>{boot.seasons.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select><select value={grade} onChange={e=>setGrade(e.target.value)}><option value="">Tüm sınıflar</option>{boot.grades.map(g=><option value={g.id} key={g.id}>{g.name}</option>)}</select></Toolbar><div className="season-board">{MONTHS.map(m=><div className="month-card" key={m.v}><h3>{m.n}</h3>{(grouped[m.v]||[]).map((x:any)=><div className="exam-event" key={x.id}><span>{fmtShort(x.application_start_date)}</span><b>{x.grade_name} · {x.publisher_short}</b><small>{x.name}</small><em>Son sipariş {fmtShort(x.last_order_date)}</em></div>)}{!(grouped[m.v]||[]).length&&<small className="muted">Planlı sınav yok</small>}</div>)}</div></>}
function groupByMonth(items:any[],key:string){return items.reduce((a:any,x:any)=>{const d=x[key];if(d){const m=String(d).slice(5,7);(a[m]||=[]).push(x)}return a},{})}

