function Institutions({boot,sub,user,refreshBoot}:{boot:Bootstrap;sub:string;user:User;refreshBoot:()=>Promise<void>}){if(sub==='Deneme Planları')return <PlanBuilder boot={boot} user={user}/>;if(sub==='Kurum Takvimleri')return <InstitutionCalendar boot={boot} user={user}/>;return <InstitutionList boot={boot} user={user} refreshBoot={refreshBoot}/>}
