function ErpInstitutionModal({close,choose}:{close:()=>void;choose:(x:any)=>void}){const[q,setQ]=useState(''),[items,setItems]=useState<any[]>([]),[msg,setMsg]=useState('');const search=async()=>{const d=await api(`/api/erp/institutions?q=${encodeURIComponent(q)}`);setItems(d.items||[]);setMsg(d.message||(!d.configured?'ERP bağlantısı henüz tanımlı değil. Manuel kurum ekleme kullanılabilir.':''))};return <Modal title="ERP'den cari seç" close={close}><div className="inline-search"><SearchBox value={q} set={setQ}/><button className="btn primary" onClick={search}>Carileri Getir</button></div>{msg&&<div className="info-box">{msg}</div>}<div className="erp-list">{items.map((x:any,i)=><button key={x.id||i} onClick={()=>choose(x)}><b>{x.name||x.title||x.unvan}</b><small>{x.code||x.customer_code||x.cari_kod||'Kod yok'} · {x.district||x.ilce||''}</small></button>)}</div></Modal>}
